def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    my_hist = [h[0] for h in history]
    opp_hist = [h[1] for h in history]
    last_my = my_hist[-1]
    last_opp = opp_hist[-1]

    opp_c = opp_hist.count('C')
    opp_d = n - opp_c

    # If opponent is mostly defecting, defect
    if opp_d > n * 0.6:
        return 'D'

    # If last 3 opponent moves are all D, defect
    if n >= 3 and opp_hist[-1] == 'D' and opp_hist[-2] == 'D' and opp_hist[-3] == 'D':
        return 'D'

    # Pushover check: if we have defected and opponent never retaliated, exploit.
    my_defections = [i for i in range(n) if my_hist[i] == 'D']
    if my_defections:
        observed_retaliation = False
        retaliated = False
        for i in my_defections:
            if i + 1 < n:
                observed_retaliation = True
                if opp_hist[i+1] == 'D':
                    if (i == 0 or opp_hist[i] == 'C') or opp_hist[i+1] == my_hist[i]:
                        retaliated = True
                        break
        if observed_retaliation and not retaliated:
            return 'D'

    # If opponent just defected
    if last_opp == 'D':
        if last_my == 'D':
            # DD
            if n >= 4 and opp_hist[-4:].count('D') >= 3:
                return 'D'
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        else:
            # CD
            # Forgive if overall cooperation is high
            if opp_c >= 10 and opp_d < 10:
                if rng.random() < 0.8:
                    return 'C'
            elif opp_d * 2 < n:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'

    # Opponent cooperated last round
    if last_my == 'D':
        # DC: cooperate to test if they retaliate
        return 'C'

    # Both cooperated (CC)
    if not my_defections:
        # Probe at n=50 to test retaliation if opponent has been fully cooperative
        if n == 50:
            return 'D'
    # Occasional exploit if opponent has long C run
    run_c = 0
    for a in reversed(opp_hist):
        if a == 'C':
            run_c += 1
        else:
            break
    if run_c >= 8 and n >= 20:
        if rng.random() < 0.1:
            return 'D'
    return 'C'
